&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_mythiques_0&quot; href=&quot;#R&#232;gles_mythiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Mythiques.html&quot; title=&quot;Pr&#233;sentation des r&#232;gles mythiques&quot;&gt;Pr&#233;sentation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique.html&quot; title=&quot;Glossaire mythique&quot;&gt;glossaire mythique&lt;/a&gt;)&lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton1&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;1&#39;);&quot; onmouseout=&quot;outButton(&#39;1&#39;);&quot; onclick=&quot;expandMenu(&#39;1&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mener-Une-Partie-Mythique.html&quot; title=&quot;Mener une partie mythique&quot;&gt;Mener une partie mythique&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;1&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Structure-Du-R&#233;cit-Mythique.html&quot; title=&quot;La structure du r&#233;cit mythique&quot;&gt;La structure du r&#233;cit mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#232;mes-Mythiques.html&quot; title=&quot;Les th&#232;mes mythiques&quot;&gt;Les th&#232;mes mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conception-Des-Rencontres-Mythiques.html&quot; title=&quot;Conception des rencontres mythiques&quot;&gt;La conception des rencontres mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;preuves-Mythiques.html&quot; title=&quot;Les &#233;preuves mythiques&quot;&gt;Les &#233;preuves mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faveurs-Mythiques.html&quot; title=&quot;Les faveurs mythiques&quot;&gt;Les faveurs mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sc&#233;l&#233;rats-Mythiques-R&#233;currents.html&quot; title=&quot;Sc&#233;l&#233;rats mythiques r&#233;currents&quot;&gt;Les sc&#233;l&#233;rats mythiques r&#233;currents&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fauts-Mythiques.html&quot; title=&quot;Les d&#233;fauts mythiques&quot;&gt;Les d&#233;fauts mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Id&#233;es-Daventures-Mythiques.html&quot; title=&quot;Id&#233;es d&amp;#39;aventures mythiques&quot;&gt;Id&#233;es d’aventures mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton2&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;2&#39;);&quot; onmouseout=&quot;outButton(&#39;2&#39;);&quot; onclick=&quot;expandMenu(&#39;2&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Personnage-Mythique.html&quot; title=&quot;Cr&#233;ation d&amp;#39;un personnage mythique&quot;&gt;Cr&#233;ation d&#39;un personnage mythique&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;2&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;Voie de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Archimage-Mythique.html&quot; title=&quot;L&amp;#39;archimage mythique&quot;&gt;archimage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-De-Larchimage-Mythique.html&quot; title=&quot;Aptitudes de voie de l&amp;#39;archimage mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Champion-Mythique.html&quot; title=&quot;Le champion mythique&quot;&gt;champion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Champion-Mythique.html&quot; title=&quot;Aptitudes de voie du champion mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Filou-Mythique.html&quot; title=&quot;Le filou mythique&quot;&gt;filou&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Filou-Mythique.html&quot; title=&quot;Aptitudes de voie du filou mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;rophante-Mythique.html&quot; title=&quot;Le hi&#233;rophante mythique&quot;&gt;hi&#233;rophante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Hi&#233;rophante-Mythique.html&quot; title=&quot;Aptitudes de voie du hi&#233;rophante mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;chal-Mythique.html&quot; title=&quot;Le mar&#233;chal mythique&quot;&gt;mar&#233;chal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Mar&#233;chal-Mythique.html&quot; title=&quot;Aptitudes de voie du mar&#233;chal mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Protecteur-Mythique.html&quot; title=&quot;Le protecteur mythique&quot;&gt;protecteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;Aptitudes de voie universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Des-Enfants-Divins-Mythiques.html&quot; title=&quot;Aptitudes de voie des enfants divins mythiques&quot;&gt;Aptitudes de voie des enfants divins&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;Options de personnage mythiques&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;Les dons mythiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;tableau&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton4&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;4&#39;);&quot; onmouseout=&quot;outButton(&#39;4&#39;);&quot; onclick=&quot;expandMenu(&#39;4&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les h&#233;ros mythiques, malgr&#233; tous leurs pouvoirs, restent toutefois des personnes avec leurs probl&#232;mes et leurs d&#233;fauts. Nombre de ces individus l&#233;gendaires sont affubl&#233;s de d&#233;fauts tout aussi l&#233;gendaires qui peuvent au final causer leur perte. &#192; cause de l’immense pouvoir dont disposent les h&#233;ros, ces faiblesses et d&#233;faillances sont souvent dramatiques et leurs ennemis chercheront &#224; les exploiter.&lt;br /&gt;&lt;br /&gt;Les d&#233;fauts mythiques suivants sont des r&#232;gles optionnelles que le MJ peut inclure dans une campagne mythique, afin de simuler la nature des h&#233;ros d’autrefois. Les personnages sont ainsi victimes d’un mal particulier qui se manifeste dans certaines situations. Ce mal ne peut &#234;tre att&#233;nu&#233; ni soign&#233; avec le temps, c’est un d&#233;faut qui fait int&#233;gralement partie de leur nature mythique.&lt;br /&gt;&lt;br /&gt;Les d&#233;fauts n’offrent aucun avantage majeur aux personnages ; leur int&#233;gration dans une partie sert uniquement &#224; am&#233;liorer l’aspect th&#233;&#226;tral du jeu et non &#224; cr&#233;er un personnage optimal. Le MJ devrait peser le pour et le contre avec minutie avant de les int&#233;grer dans le jeu et d&#233;cider si cet ajout permet de d&#233;velopper une histoire globale plus int&#233;ressante et, plus important encore, si le plaisir de jeu est augment&#233;.&lt;br /&gt;&lt;br /&gt;Si vous d&#233;cidez d’int&#233;grer les d&#233;fauts mythiques dans le jeu, les personnages les obtiennent quand ils acqui&#232;rent le &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, au moment de l’&lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Ascension.html&quot; title=&quot;Ascension&quot;&gt;ascension&lt;/a&gt;. Vous pouvez s&#233;lectionner vous-m&#234;me ces d&#233;fauts, pour coller au th&#232;me li&#233; &#224; l’ascension des personnages, ou vous pouvez autoriser les joueurs &#224; choisir les d&#233;fauts de leur personnage qu’ils int&#233;greront dans son histoire. Les d&#233;fauts mythiques suivants sont des exemples que vous pouvez inclure dans votre jeu.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aversion magique&lt;a class=&quot;headeranchor&quot; id=&quot;Aversion_magique_0&quot; href=&quot;#Aversion_magique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Malgr&#233; son pouvoir, le personnage sait qu’un type de magie provoquera sa perte. Les individus qui usent de cette magie repr&#233;sentent donc pour lui un grand danger. S&#233;lectionnez une &lt;a class=&quot;pagelink&quot; href=&quot;&#201;coles-De-Magie.html&quot; title=&quot;&#233;cole de magie&quot;&gt;&#233;cole de magie&lt;/a&gt; (&#224; l’exception de la divination). &#192; chaque fois que le personnage effectue un jet de sauvegarde contre un sort ou un effet de cette &#233;cole, il subit un malus de -4 &#224; ce jet. Les effets de ces sorts (s’ils sont n&#233;fastes) durent deux fois plus longtemps en cas de sauvegarde rat&#233;e. De plus, tous les sorts et les effets de cette &#233;cole utilis&#233;s contre le personnage sont toujours consid&#233;r&#233;s comme provenant d’une source mythique. Il est &#233;galement possible que le personnage ne puisse b&#233;n&#233;ficier des sorts et des effets issus de l’&#233;cole s&#233;lectionn&#233;e, &#224; la discr&#233;tion du MJ.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;pendance&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;pendance_1&quot; href=&quot;#D&#233;pendance_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le h&#233;ros mange ou boit un unique type de nourriture ou de boisson et son pouvoir faiblit s’il n’en dispose plus. Choisissez un type sp&#233;cifique de nourriture ou de boisson (&#224; l’exception de l’eau). Si le personnage ne consomme pas cette nourriture ou cette boisson au moins une fois par jour, son &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; faiblit peu &#224; peu. Apr&#232;s un jour d’abstinence, le personnage ne peut plus r&#233;cup&#233;rer ses utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;. Apr&#232;s deux jours d’abstinence, il perd la totalit&#233; des pouvoirs et aptitudes conf&#233;r&#233;s par sa &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Voiemythique.html&quot; title=&quot;voie mythique&quot;&gt;voie mythique&lt;/a&gt;. Apr&#232;s trois jours, il perd la totalit&#233; de ses aptitudes mythiques, &#224; l’exception des augmentations de valeur de caract&#233;ristique, des bonus en points de vie et des &lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;dons mythiques&lt;/a&gt; suppl&#233;mentaires. Ces pouvoirs et aptitudes reviennent imm&#233;diatement d&#232;s que le personnage consomme la nourriture ou la boisson li&#233;e &#224; sa d&#233;pendance.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Faiblesse martiale&lt;a class=&quot;headeranchor&quot; id=&quot;Faiblesse_martiale_2&quot; href=&quot;#Faiblesse_martiale_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les proph&#233;ties affirment qu’une arme provoquera la mort du personnage. S&#233;lectionnez un groupe d’armes de la liste des armes du guerrier. Les armes issues du groupe s&#233;lectionn&#233; gagnent un bonus de +4 aux jets d’attaque et de d&#233;g&#226;ts effectu&#233;s contre le personnage. Si une arme issue du groupe s&#233;lectionn&#233; r&#233;ussit un coup critique contre le personnage, le multiplicateur de critique augmente de 1 ( jusqu’&#224; un maximum de &#215;4). Si le personnage b&#233;n&#233;ficie d’une r&#233;duction des d&#233;g&#226;ts, les armes du groupe s&#233;lectionn&#233; ignorent toujours cette r&#233;duction.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Faiblesse mat&#233;rielle&lt;a class=&quot;headeranchor&quot; id=&quot;Faiblesse_mat&#233;rielle_3&quot; href=&quot;#Faiblesse_mat&#233;rielle_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un mat&#233;riau sp&#233;cifique peut percer les d&#233;fenses les plus solides du personnage. S&#233;lectionnez le fer froid, l’argent ou le bois. Les armes dont la majeure partie est faite dans ce mat&#233;riau confirment automatiquement tous les coups critiques inflig&#233;s au personnage et le multiplicateur de critique augmente de 1 ( jusqu’&#224; un maximum de &#215;4). Si le personnage b&#233;n&#233;ficie d’une r&#233;duction des d&#233;g&#226;ts, les armes dont la majeure partie est faite dans le mat&#233;riau s&#233;lectionn&#233; ignorent toujours cette r&#233;duction.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Humeur changeante&lt;a class=&quot;headeranchor&quot; id=&quot;Humeur_changeante_4&quot; href=&quot;#Humeur_changeante_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le pouvoir d&#233;tenu par le personnage perturbe son esprit aux moments cruciaux. &#192; chaque fois qu’il est touch&#233; par un coup critique ou qu’il rate un jet de sauvegarde contre un sort ou un pouvoir sp&#233;cial de type mental, le personnage est &#233;galement confus pendant 1d4 rounds.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Orgueil d&#233;mesur&#233;&lt;a class=&quot;headeranchor&quot; id=&quot;Orgueil_d&#233;mesur&#233;_5&quot; href=&quot;#Orgueil_d&#233;mesur&#233;_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage est toujours le premier, le meilleur, il est de loin sup&#233;rieur aux autres. Son pouvoir est in&#233;gal&#233; et il en est conscient. Il b&#233;n&#233;ficie d’un bonus de moral de +4 aux jets de sauvegarde contre la terreur. &#192; chaque fois qu’il r&#233;ussit un jet de sauvegarde contre un effet qui inflige normalement l’&#233;tat pr&#233;judiciable secou&#233;, effray&#233; ou paniqu&#233;, il devient &#224; la place chancelant pendant une dur&#233;e &#233;quivalente &#224; celle de l’effet initial car il passe une partie de chaque round &#224; se vanter de sa prouesse. S’il rate un jet de sauvegarde contre un tel effet, la dur&#233;e de cet effet est doubl&#233;e alors que le personnage est couvert de honte ou rong&#233; par le doute.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Rage folle&lt;a class=&quot;headeranchor&quot; id=&quot;Rage_folle_6&quot; href=&quot;#Rage_folle_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La rage du personnage est fonci&#232;rement bestiale et il peut difficilement la contenir. &#192; chaque fois qu’il est touch&#233; par un coup critique ou d&#233;moralis&#233; suite &#224; l’utilisation de la comp&#233;tence d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;, le personnage entre dans une rage incontr&#244;lable. Cette rage fonctionne comme l’aptitude de rage de berserker du &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt;, mais le personnage ne b&#233;n&#233;ficie d’aucun bonus aux valeurs de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; (m&#234;me s’il poss&#232;de effectivement l’aptitude de classe de rage de berserker). Cette rage limite les actions que le personnage peut accomplir et lui inflige un malus de -2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;classe d’armure&lt;/a&gt;. Elle dure un nombre de rounds &#233;gal &#224; 1d4 plus le &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; mythique du personnage, mais il n’est pas fatigu&#233; une fois cette dur&#233;e &#233;coul&#233;e. S’il poss&#232;de l’aptitude de classe de rage de berserker, cette rage n’est pas consid&#233;r&#233;e comme une utilisation de cette aptitude. Si le personnage est en rage lorsque ce d&#233;faut se manifeste, la rage de berserker prend fin et la rage folle commence.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Vuln&#233;rabilit&#233; &#233;l&#233;mentaire&lt;a class=&quot;headeranchor&quot; id=&quot;Vuln&#233;rabilit&#233;_&#233;l&#233;mentaire_7&quot; href=&quot;#Vuln&#233;rabilit&#233;_&#233;l&#233;mentaire_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une &#233;nergie &#233;l&#233;mentaire particuli&#232;re produit un effet n&#233;faste sur le pouvoir du personnage et le blesse bien plus gri&#232;vement que les autres. S&#233;lectionnez l’une des &#233;nergies destructives suivantes : acide, froid, &#233;lectricit&#233; ou feu. Le personnage subit le double des d&#233;g&#226;ts normalement &#224; chaque fois que ces d&#233;g&#226;ts proviennent du type d’&#233;nergie s&#233;lectionn&#233;e. Le personnage ne peut jamais b&#233;n&#233;ficier d’une r&#233;sistance ou d’une immunit&#233; &#224; cette &#233;nergie. Lorsqu’un effet de ce type est utilis&#233; contre lui, on consid&#232;re toujours qu’il est produit par une source mythique.
